Вот исправленный код с использованием `Spatie\PdfToImage\Pdf`:

```php
<?php

namespace App\Services;

use App\Models\Document;
use App\Models\DocumentPage;
use Illuminate\Support\Facades\Storage;
use Spatie\PdfToImage\Pdf;
use Throwable;

class PdfConverterService
{
    public function convert(Document $document): int
    {
        if (!$document->pdf_path) {
            throw new \RuntimeException('PDF не загружен.');
        }

        $pdfPath = storage_path('app/public/' . $document->pdf_path);

        if (!file_exists($pdfPath)) {
            throw new \RuntimeException('PDF-файл не найден на диске.');
        }

        $this->clearPages($document);

        $pagesDir = $document->storageDirectory() . '/pages';
        Storage::disk('public')->makeDirectory($pagesDir);

        $gsPath = config('infomat.ghostscript_path');
        if ($gsPath && file_exists($gsPath)) {
            $gsDir = dirname(str_replace('/', DIRECTORY_SEPARATOR, $gsPath));
            $path = getenv('PATH') ?: '';
            putenv('PATH=' . $gsDir . PATH_SEPARATOR . $path);
        }

        $pdf = new Pdf($pdfPath);
        $pdf->setResolution((int) config('infomat.pdf_dpi', 150));
        $pdf->setOutputFormat('jpg');
        $pdf->setCompressionQuality(85);

        $pageCount = $pdf->getNumberOfPages();

        for ($page = 1; $page <= $pageCount; $page++) {
            $filename = sprintf('page-%03d.jpg', $page);
            $relativePath = $pagesDir . '/' . $filename;
            $fullPath = storage_path('app/public/' . $relativePath);

            $pdf->setPage($page)->saveImage($fullPath);

            DocumentPage::create([
                'document_id' => $document->id,
                'page_number' => $page,
                'image_path' => $relativePath,
            ]);
        }

        $document->update([
            'page_count' => $pageCount,
            'conversion_status' => Document::STATUS_DONE,
            'conversion_error' => null,
        ]);

        return $pageCount;
    }

    public function convertSafely(Document $document): bool
    {
        try {
            $this->convert($document);

            return true;
        } catch (Throwable $exception) {
            $document->update([
                'conversion_status' => Document::STATUS_FAILED,
                'conversion_error' => $exception->getMessage(),
                'page_count' => 0,
            ]);

            return false;
        }
    }

    protected function clearPages(Document $document): void
    {
        $document->pages()->delete();
        Storage::disk('public')->deleteDirectory($document->storageDirectory() . '/pages');
    }
}
```

