(function () {
    const outputField = document.getElementById('output');
    const keyboardContainer = document.getElementById('keyboard');
    const state = { caps: false, shift: false, lang: 'ru' };
    const layoutData = [
        ['1', '2', '3', '4', '5', '6', '7', '8', '9', '0'],
        ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p'],
        ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
        ['z', 'x', 'c', 'v', 'b', 'n', 'm'],
        ['backspace', 'caps', 'shift', 'space']
    ];

    function getChar(key) {
        if (state.caps || key.kind === 'char' && state.shift) {
            return key.char.toUpperCase();
        }
        return key.char.toLowerCase();
    }

    function insertText(text) {
        const pos = outputField.selectionStart;
        const before = outputField.value.substring(0, pos);
        const after = outputField.value.substring(pos, outputField.value.length);
        outputField.value = before + text + after;
        const newPos = pos + text.length;
        outputField.setSelectionRange(newPos, newPos);
    }

    function handleBackspace() {
        const pos = outputField.selectionStart;
        if (pos > 0) {
            const before = outputField.value.substring(0, pos - 1);
            const after = outputField.value.substring(pos, outputField.value.length);
            outputField.value = before + after;
            outputField.setSelectionRange(pos - 1, pos - 1);
        }
    }

    function moveCursor(direction) {
        const pos = outputField.selectionStart;
        if (direction === 'left' && pos > 0) {
            outputField.setSelectionRange(pos - 1, pos - 1);
        } else if (direction === 'right' && pos < outputField.value.length) {
            outputField.setSelectionRange(pos + 1, pos + 1);
        }
    }

    function renderKeyboard() {
        keyboardContainer.innerHTML = '';
        layoutData.forEach(row => {
            const rowDiv = document.createElement('div');
            rowDiv.className = 'row';
            row.forEach(key => {
                const btn = document.createElement('button');
                btn.type = 'button';
                const sizeClass = key.width ? `key-${key.width}` : 'key-md';
                btn.className = `key ${sizeClass}`;
                btn.textContent = getChar(key);
                if ((key.kind === 'caps' && state.caps) ||
                    (key.kind === 'shift' && state.shift) ||
                    (key.kind === 'switch' && state.lang === 'en')) {
                    btn.classList.add('active');
                }
                btn.addEventListener('click', () => handleKey(key), { passive: true });
                btn.addEventListener('touchstart', (e) => e.preventDefault(), { passive: false });
                rowDiv.appendChild(btn);
            });
            keyboardContainer.appendChild(rowDiv);
        });
    }

    function handleKey(key) {
        switch (key.kind) {
            case 'char':
                insertText(getChar(key));
                state.shift = false;
                break;
            case 'space':
                insertText(' ');
                break;
            case 'tab':
                insertText('  ');
                break;
            case 'enter':
                insertText('\n');
                break;
            case 'backspace':
                handleBackspace();
                break;
            case 'caps':
                state.caps = !state.caps;
                break;
            case 'shift':
                state.shift = !state.shift;
                break;
            case 'switch':
                state.lang = state.lang === 'ru' ? 'en' : 'ru';
                break;
            case 'arrow':
                moveCursor(key.output === 'left' ? 'left' : 'right');
                break;
        }
        renderKeyboard();
    }

    window.addEventListener('keydown', (e) => {
        if (e.altKey && e.shiftKey) {
            e.preventDefault();
            state.lang = state.lang === 'ru' ? 'en' : 'ru';
            renderKeyboard();
        }
    });

    renderKeyboard();
    outputField.focus();
})();
